import pandas as pd
import numpy as np

file_path = '/data/programme_monthly_spend.xlsx'
df_raw = pd.read_excel(file_path, sheet_name='Monthly Spend', header=None)

# Identify programme rows
prog_indices = []
for i, row in df_raw.iterrows():
    val = row[0]
    if isinstance(val, str) and val.startswith('PRG-'):
        prog_indices.append(i)

# Columns 4 to 9 inclusive are Apr, May, Jun, Jul, Aug, Sep
cols = [4,5,6,7,8,9]
total = 0.0
details = []
for i in prog_indices:
    row_vals = []
    for c in cols:
        v = df_raw.iat[i, c]
        # treat '-', '–', blank, NaN as zero
        if pd.isna(v):
            num = 0
        elif isinstance(v, str):
            s = v.strip()
            if s in ['-', '–', '']:
                num = 0
            else:
                # try convert
                try:
                    num = float(s.replace(',', ''))
                except:
                    num = 0
        else:
            try:
                num = float(v)
            except:
                num = 0
        row_vals.append(num)
    row_sum = sum(row_vals)
    details.append((df_raw.iat[i,0], row_vals, row_sum))
    total += row_sum

print("Total spend April-September 2025 (sum of monthly columns):", total)
print("Details per programme:")
for prog, vals, s in details:
    print(prog, vals, s)
print("Sum of Six-month Total column for comparison:")
six_month_total = 0
for i in prog_indices:
    v = df_raw.iat[i,10]
    if pd.isna(v):
        num = 0
    else:
        try:
            num = float(v)
        except:
            num = 0
    six_month_total += num
print(six_month_total)
